contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == dummy);
        uint256 vBefore = c.value(); if (__ESBMC_reverted()) return;
        uint256 remainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 vAfter = c.value(); if (__ESBMC_reverted()) return;
        uint256 expectedBase = vBefore > remainingBefore ? remainingBefore : vBefore;
        assert(reverted ? vAfter == vBefore : vAfter == (expectedBase / 100000) * 99999);
    }

    receive() external payable {}
}

