pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint256 vBefore;
        try c.value() returns (uint256 __r) { vBefore = __r; } catch { return; }
        uint256 remainingBefore;
        try c.totalRemaining() returns (uint256 __r) { remainingBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens() { reverted = false; } catch { reverted = true; }
        uint256 vAfter;
        try c.value() returns (uint256 __r) { vAfter = __r; } catch { return; }
        uint256 expectedBase = vBefore > remainingBefore ? remainingBefore : vBefore;
        assertTrue(reverted ? vAfter == vBefore : vAfter == (expectedBase / 100000) * 99999);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
